namespace optiling {
const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_W = 64;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvDepthwise2dSquareInputAsymmetricKernelCustomTilingData tiling;

    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1);
    bool hasBias = (context->GetInputShape(2) != nullptr && context->GetInputShape(2)->GetShapeSize() > 0);

    // x: (N, C, H, W), w: (C, 1, KH, 1)
    uint32_t n = static_cast<uint32_t>(x_shape->GetDim(0));
    uint32_t c = static_cast<uint32_t>(x_shape->GetDim(1));
    uint32_t h = static_cast<uint32_t>(x_shape->GetDim(2));
    uint32_t w = static_cast<uint32_t>(x_shape->GetDim(3));

    uint32_t kh = static_cast<uint32_t>(w_shape->GetDim(2));
    uint32_t kw = static_cast<uint32_t>(w_shape->GetDim(3)); // expected 1

    int64_t stride  = GetIntAttr(context, "stride", 1);
    int64_t padding = GetIntAttr(context, "padding", 0);
    int64_t dilation= GetIntAttr(context, "dilation", 1);

    // PyTorch conv2d output size formula:
    // out = floor((in + 2*pad - dilation*(kernel-1) - 1) / stride + 1)
    uint32_t hout = static_cast<uint32_t>((static_cast<int64_t>(h) + 2*padding - dilation*(static_cast<int64_t>(kh)-1) - 1) / stride + 1);
    uint32_t wout = static_cast<uint32_t>((static_cast<int64_t>(w) + 2*padding - dilation*(static_cast<int64_t>(kw)-1) - 1) / stride + 1);

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_n(n);
    tiling.set_c(c);
    tiling.set_h(h);
    tiling.set_w(w);
    tiling.set_kh(kh);
    tiling.set_kw(kw);
    tiling.set_stride(static_cast<uint32_t>(stride));
    tiling.set_padding(static_cast<uint32_t>(padding));
    tiling.set_dilation(static_cast<uint32_t>(dilation));
    tiling.set_hout(hout);
    tiling.set_wout(wout);
    tiling.set_hasBias(hasBias ? 1U : 0U);
    tiling.set_tileW(TILE_W);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *workspace = context->GetWorkspaceSizes(1);
    workspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

